python3 -c "
import math,statistics as s,json
d=['2024-03-04','2024-03-05','2024-03-06','2024-03-07','2024-03-08','2024-03-11']
c={'AAA':[50.0,50.5,49.8,50.9,51.2,50.6],'BBB':[120.0,118.4,119.1,121.3,120.2,122.0]}
r={k:[math.log(v[i]/v[i-1]) for i in range(1,6)] for k,v in c.items()}
vol={k:[None if i<2 else s.stdev(x[i-2:i])*math.sqrt(252) for i in range(5)] for k,x in r.items()}
print(json.dumps({'r':r,'vol':vol}))
x=r['AAA'];print(252*s.mean(x), math.sqrt(252)*s.stdev(x), 252*s.mean(x)/(math.sqrt(252)*s.stdev(x)))
w=[1];[w.append(w[-1]*math.exp(v)) for v in x];pk=0;dd=0
for i,v in enumerate(w):
  pk=max(pk,v);dd=min(dd,v/pk-1)
print(w,dd)
"

